#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int data; struct Node *next; } Node;

/* 带哨兵：不存在“删头节点”的特例分支 */
Node *remove_value(Node *head, int v) {
    Node dummy = {0, head};
    Node *prev = &dummy;
    while (prev->next && prev->next->data != v) prev = prev->next;
    if (prev->next) {
        Node *del = prev->next;
        prev->next = del->next;
        free(del);
    }
    return dummy.next;                 /* 新头 */
}

void print_list(const char *tag, Node *h) {
    printf("%s: ", tag);
    for (Node *p = h; p; p = p->next) printf("%d%s", p->data, p->next ? " -> " : "");
    printf("\n");
}

int main(void) {
    /* 构造 7 -> 3 -> 5 -> 3 -> 9 */
    int vals[] = {7, 3, 5, 3, 9};
    Node *head = NULL, *tail = NULL;
    for (int i = 0; i < 5; i++) {
        Node *nd = malloc(sizeof(Node));
        nd->data = vals[i]; nd->next = NULL;
        if (!head) head = tail = nd; else { tail->next = nd; tail = nd; }
    }
    print_list("原链表      ", head);
    head = remove_value(head, 3);
    print_list("删除首个 3 后", head);
    head = remove_value(head, 7);        /* 删头节点：代码路径与上一行完全相同 */
    print_list("删除头 7 后 ", head);
    printf("注意：删除头节点没有走任何特殊分支\n");
    return 0;
}
